public class NicknameLookupTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.Map<String, String> nicks = new java.util.HashMap<>();
        nicks.put("sam", "Sammy");
        nicks.put("pat", "Patty");
        nicks.put("kim", "");
        nicks.put("lee", "   ");
        check("nickname for sam", java.util.Optional.of("Sammy"), NicknameLookup.nickname(nicks, "sam"));
        check("nickname for pat", java.util.Optional.of("Patty"), NicknameLookup.nickname(nicks, "pat"));
        check("empty-string value is filtered out", java.util.Optional.empty(), NicknameLookup.nickname(nicks, "kim"));
        check("whitespace-only value is filtered out", java.util.Optional.empty(), NicknameLookup.nickname(nicks, "lee"));
        check("missing key", java.util.Optional.empty(), NicknameLookup.nickname(nicks, "zoe"));
        java.util.Optional<String> samNick = NicknameLookup.nickname(nicks, "sam");
        check("sam's nickname is present", true, samNick != null && samNick.isPresent());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

